// Dynamic messages from APIs and older components. These preserve variables such as a store,
// product, date, plan or count while translating the surrounding UI wording.
const dynamicRules: Array<[RegExp, (m: RegExpMatchArray, l: Exclude<SiteLanguage,'en'>) => string]> = [
  [/^Updated (.+)$/i, (m,l)=> l==='hi'?`अपडेट ${m[1]}`:l==='gu'?`અપડેટ ${m[1]}`:`Mis à jour ${m[1]}`],
  [/^Valid until (.+)$/i, (m,l)=> l==='hi'?`${m[1]} तक मान्य`:l==='gu'?`${m[1]} સુધી માન્ય`:`Valide jusqu’au ${m[1]}`],
  [/^Valid (.+) – (.+)$/i, (m,l)=> l==='hi'?`${m[1]} से ${m[2]} तक मान्य`:l==='gu'?`${m[1]} થી ${m[2]} સુધી માન્ય`:`Valide du ${m[1]} au ${m[2]}`],
  [/^Step (\d+)$/i, (m,l)=> l==='hi'?`चरण ${m[1]}`:l==='gu'?`પગલું ${m[1]}`:`Étape ${m[1]}`],
  [/^(\d+) items?$/i, (m,l)=> l==='hi'?`${m[1]} वस्तुएँ`:l==='gu'?`${m[1]} વસ્તુઓ`:`${m[1]} articles`],
  [/^(\d+) products?$/i, (m,l)=> l==='hi'?`${m[1]} उत्पाद`:l==='gu'?`${m[1]} પ્રોડક્ટ્સ`:`${m[1]} produits`],
  [/^Missing: (.+)$/i, (m,l)=> l==='hi'?`नहीं मिला: ${m[1]}`:l==='gu'?`ઓછું/ગુમ: ${m[1]}`:`Manquant : ${m[1]}`],
  [/^Near (.+)$/i, (m,l)=> l==='hi'?`${m[1]} के पास`:l==='gu'?`${m[1]} નજીક`:`Près de ${m[1]}`],
  [/^Cache valid until (.+)$/i, (m,l)=> l==='hi'?`कैश ${m[1]} तक मान्य`:l==='gu'?`કૅશ ${m[1]} સુધી માન્ય`:`Cache valide jusqu’au ${m[1]}`],
  [/^Show all deals \((\d+)\)$/i, (m,l)=> l==='hi'?`सभी ऑफ़र दिखाएं (${m[1]})`:l==='gu'?`બધી ડીલ બતાવો (${m[1]})`:`Afficher toutes les offres (${m[1]})`],
  [/^Show fewer$/i, (_m,l)=> l==='hi'?`कम दिखाएं`:l==='gu'?`ઓછું બતાવો`:`Afficher moins`],
  [/^(\d+) deals? • (\d+) flyers?$/i, (m,l)=> l==='hi'?`${m[1]} ऑफ़र • ${m[2]} फ्लायर`:l==='gu'?`${m[1]} ડીલ • ${m[2]} ફ્લાયર`:`${m[1]} offres • ${m[2]} circulaires`],
  [/^(\d+) deals?$/i, (m,l)=> l==='hi'?`${m[1]} ऑफ़र`:l==='gu'?`${m[1]} ડીલ`:`${m[1]} offres`],
  [/^(\d+) flyer stores are available for this postal code\. Select any stores below, or leave all unselected to use the provider's local grocery set\.$/i, (m,l)=> l==='hi'?`${m[1]} फ्लायर स्टोर इस पोस्टल कोड के लिए उपलब्ध हैं। नीचे कोई भी स्टोर चुनें, या प्रदाता के स्थानीय ग्रोसरी सेट के लिए सभी को अनचुना छोड़ें।`:l==='gu'?`${m[1]} ફ્લાયર સ્ટોર્સ આ પોસ્ટલ કોડ માટે ઉપલબ્ધ છે. નીચે કોઈપણ સ્ટોર પસંદ કરો અથવા પ્રોવાઇડરના સ્થાનિક ગ્રોસરી સેટ માટે બધા અનપસંદ રાખો.`:`${m[1]} magasins avec circulaires sont disponibles pour ce code postal. Sélectionnez les magasins souhaités ou ne sélectionnez rien pour utiliser l’ensemble local du fournisseur.`],
  [/^(\d+) stores selected$/i, (m,l)=> l==='hi'?`${m[1]} स्टोर चुने गए`:l==='gu'?`${m[1]} સ્ટોર્સ પસંદ`:`${m[1]} magasins sélectionnés`],
  [/^(\d+) stores selected • max 12$/i, (m,l)=> l==='hi'?`${m[1]} स्टोर चुने गए • अधिकतम 12`:l==='gu'?`${m[1]} સ્ટોર્સ પસંદ • મહત્તમ 12`:`${m[1]} magasins sélectionnés • max. 12`],
  [/^All local stores • select up to 12$/i, (_m,l)=> l==='hi'?`सभी स्थानीय स्टोर • अधिकतम 12 चुनें`:l==='gu'?`બધા સ્થાનિક સ્ટોર્સ • વધુમાં વધુ 12 પસંદ કરો`:`Tous les magasins locaux • jusqu’à 12`],
  [/^Flyer area:\s*(.+)$/i, (m,l)=> l==='hi'?`फ्लायर क्षेत्र: ${m[1]}`:l==='gu'?`ફ્લાયર વિસ્તાર: ${m[1]}`:`Zone de circulaire : ${m[1]}`],
  [/^Requested quantity:\s*(.+)$/i, (m,l)=> l==='hi'?`आवश्यक मात्रा: ${m[1]}`:l==='gu'?`જરૂરી માત્રા: ${m[1]}`:`Quantité demandée : ${m[1]}`],
  [/^was \$(.+)$/i, (m,l)=> l==='hi'?`पहले $${m[1]}`:l==='gu'?`પહેલાં $${m[1]}`:`avant $${m[1]}`],
  [/^Showing (\d+) active weekly flyer deals(?: for ‘(.+)’)? across (\d+) local merchants from (.+)\. Flyer prices are promotional prices valid only for the displayed dates\.$/i,
    (m,l)=> l==='hi'?`${m[1]} सक्रिय साप्ताहिक फ्लायर ऑफ़र${m[2]?` ‘${m[2]}’ के लिए`:''}, ${m[3]} स्थानीय स्टोर से दिखाए जा रहे हैं (${m[4]})। फ्लायर कीमतें केवल दिखाई गई तारीखों के लिए मान्य प्रचार कीमतें हैं।`:l==='gu'?`${m[1]} સક્રિય સાપ્તાહિક ફ્લાયર ડીલ${m[2]?` ‘${m[2]}’ માટે`:''}, ${m[3]} સ્થાનિક સ્ટોરમાંથી બતાવવામાં આવી રહી છે (${m[4]}). ફ્લાયર ભાવ ફક્ત બતાવેલી તારીખો માટે માન્ય પ્રમોશનલ ભાવ છે.`:`${m[1]} offres actives${m[2]?` pour « ${m[2]} »`:''} provenant de ${m[3]} commerçants locaux (${m[4]}). Les prix des circulaires sont promotionnels et valables uniquement aux dates indiquées.`],
];

